#![cfg(any(feature="test-hook",feature="owner-leases"))]
use atlas_sqlcipher_proof::Vault;
#[test] fn rescue_is_isolated_and_not_plaintext(){let path=std::env::temp_dir().join(format!("atlas-rescue-{}.vault",uuid::Uuid::new_v4()));let mut v=Vault::create(&path,"test-password").unwrap();v.put_note("note","Original","original body").unwrap();v.register_rescue_session_guarded("note","session-a",||Ok(())).unwrap();v.register_rescue_session_guarded("note","session-b",||Ok(())).unwrap();v.save_rescue_draft_guarded("note","session-a","Rescue","unique-private-rescue-82749",||Ok(())).unwrap();v.save_rescue_draft_guarded("note","session-b","Other","another rescue",||Ok(())).unwrap();assert!(v.save_rescue_draft_guarded("note","invalid","Bad","Bad",||Ok(())).is_err());assert_eq!(v.get_note("note").unwrap(),"original body");assert_eq!(v.get_rescue_draft("note","session-a").unwrap().unwrap().1,"unique-private-rescue-82749");drop(v);let bytes=std::fs::read(&path).unwrap();assert!(!bytes.windows(b"unique-private-rescue-82749".len()).any(|w|w==b"unique-private-rescue-82749"));let v=Vault::open(&path,"test-password").unwrap();assert_eq!(v.get_rescue_draft("note","session-a").unwrap().unwrap().1,"unique-private-rescue-82749");assert_eq!(v.get_rescue_draft("note","session-b").unwrap().unwrap().1,"another rescue");drop(v);std::fs::remove_file(path).unwrap();}
#[test] fn rescue_survives_protection_conversion_both_ways(){let root=std::env::temp_dir().join(format!("atlas-rescue-convert-{}",uuid::Uuid::new_v4()));let vault_path=root.with_extension("vault");let out=root.with_extension("plain");atlas_native_storage_contract::create_workspace(&root).unwrap();let args=vec!["atlas".into(),"create-note".into(),root.to_string_lossy().into_owned(),"Original".into(),"Body".into()];let id=atlas_native_storage_contract::execute(&args).unwrap()["id"].as_str().unwrap().to_owned();atlas_native_storage_contract::register_rescue_session(&root,&id,"hash").unwrap();atlas_native_storage_contract::save_rescue_draft(&root,&id,"hash","Title","rescue-conversion-private").unwrap();let v=Vault::import_plain(&root,&vault_path,"password").unwrap();assert_eq!(v.get_rescue_draft(&id,"hash").unwrap().unwrap().1,"rescue-conversion-private");v.set_workspace_name_guarded("test",||Ok(())).unwrap();v.export_plain(&out).unwrap();drop(v);assert_eq!(atlas_native_storage_contract::get_rescue_draft(&out,&id,"hash").unwrap().unwrap().1,"rescue-conversion-private");std::fs::remove_dir_all(root).unwrap();std::fs::remove_dir_all(out).unwrap();std::fs::remove_file(vault_path).unwrap();}
#[test] fn rescue_purged_with_deleted_note(){let path=std::env::temp_dir().join(format!("atlas-rescue-purge-{}.vault",uuid::Uuid::new_v4()));let mut v=Vault::create(&path,"test-password").unwrap();v.put_note("note","Title","Body").unwrap();v.register_rescue_session_guarded("note","hash",||Ok(())).unwrap();v.save_rescue_draft_guarded("note","hash","title","secret",||Ok(())).unwrap();v.trash("note",1).unwrap();v.purge_trash_before(2).unwrap();assert!(v.get_rescue_draft("note","hash").unwrap().is_none());drop(v);std::fs::remove_file(path).unwrap();}
#[test] fn rescue_survives_encrypted_snapshot_without_plaintext(){let dir=std::env::temp_dir().join(format!("atlas-rescue-snapshot-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&dir).unwrap();let src=dir.join("source");let copy=dir.join("snapshot");let mut v=Vault::create(&src,"password").unwrap();v.put_note("note","Original","Body").unwrap();v.register_rescue_session_guarded("note","hash",||Ok(())).unwrap();v.save_rescue_draft_guarded("note","hash","title","snapshot-rescue-private-58391",||Ok(())).unwrap();v.snapshot_to(&copy,"password",|_,_|{}).unwrap();drop(v);let bytes=std::fs::read(&copy).unwrap();assert!(!bytes.windows(b"snapshot-rescue-private-58391".len()).any(|w|w==b"snapshot-rescue-private-58391"));let v=Vault::open(&copy,"password").unwrap();assert_eq!(v.get_rescue_draft("note","hash").unwrap().unwrap().1,"snapshot-rescue-private-58391");drop(v);std::fs::remove_dir_all(dir).unwrap();}
#[test] fn board_rescue_survives_encrypted_conversion_and_snapshot(){let root=std::env::temp_dir().join(format!("atlas-board-rescue-{}",uuid::Uuid::new_v4()));let vault_path=root.with_extension("vault");let snapshot=root.with_extension("snapshot");let out=root.with_extension("plain");atlas_native_storage_contract::create_workspace(&root).unwrap();atlas_native_storage_contract::board_rescue(&root,"open","hash","").unwrap();let board=r#"{"objects":[{"id":"board-sensitive-17395"}],"edges":[],"stacks":[]}"#;atlas_native_storage_contract::board_rescue(&root,"save","hash",board).unwrap();let mut v=Vault::import_plain(&root,&vault_path,"password").unwrap();v.set_workspace_name_guarded("test",||Ok(())).unwrap();assert_eq!(v.board_rescue_guarded("list","","",||Ok(())).unwrap()["drafts"][0]["board"]["objects"][0]["id"],"board-sensitive-17395");v.snapshot_to(&snapshot,"password",|_,_|{}).unwrap();assert!(!std::fs::read(&snapshot).unwrap().windows(b"board-sensitive-17395".len()).any(|w|w==b"board-sensitive-17395"));v.export_plain(&out).unwrap();drop(v);assert_eq!(atlas_native_storage_contract::board_rescue(&out,"list","","").unwrap()["drafts"][0]["board"]["objects"][0]["id"],"board-sensitive-17395");std::fs::remove_dir_all(root).unwrap();std::fs::remove_dir_all(out).unwrap();std::fs::remove_file(vault_path).unwrap();std::fs::remove_file(snapshot).unwrap();}
#[test] fn restored_agent_receipt_survives_protection_conversion(){let root=std::env::temp_dir().join(format!("atlas-restored-convert-{}",uuid::Uuid::new_v4()));let vault_path=root.with_extension("vault");let out=root.with_extension("plain");atlas_native_storage_contract::create_workspace(&root).unwrap();{let db=rusqlite::Connection::open(root.join("atlas.sqlite3")).unwrap();db.execute_batch("CREATE TABLE agent_recovery_restored(actor TEXT NOT NULL,request_id TEXT NOT NULL,object_id TEXT NOT NULL,PRIMARY KEY(actor,request_id)); INSERT INTO agent_recovery_restored VALUES('actor','request','object');").unwrap();}let v=Vault::import_plain(&root,&vault_path,"password").unwrap();v.set_workspace_name_guarded("test",||Ok(())).unwrap();v.export_plain(&out).unwrap();drop(v);let db=rusqlite::Connection::open(out.join("atlas.sqlite3")).unwrap();let value:String=db.query_row("SELECT object_id FROM agent_recovery_restored WHERE actor='actor' AND request_id='request'",[],|r|r.get(0)).unwrap();assert_eq!(value,"object");drop(db);std::fs::remove_dir_all(root).unwrap();std::fs::remove_dir_all(out).unwrap();std::fs::remove_file(vault_path).unwrap();}
